import numpy as np

def union_measure(y, D, n):
    intervals = []
    for m in range(len(y)):
        radius = D / (m + 1 + n + 1)
        intervals.append((y[m] - radius, y[m] + radius))
    intervals.sort()

    measure = 0
    if not intervals:
        return 0

    curr_start, curr_end = intervals[0]
    for next_start, next_end in intervals[1:]:
        if next_start < curr_end:
            curr_end = max(curr_end, next_end)
        else:
            measure += curr_end - curr_start
            curr_start, curr_end = next_start, next_end
    measure += curr_end - curr_start
    return measure

M = 777**2
# Use the y sequence from the greedy check_D
def get_y_sequence(D, M, N):
    y = np.zeros(N)
    y[0] = 0
    for n in range(1, N):
        intervals = []
        for m in range(n):
            radius = D / (m + 1 + n + 1)
            intervals.append((y[m] - radius, y[m] + radius))
        intervals.sort()
        current_pos = 0
        found = False
        for start, end in intervals:
            if start > current_pos:
                y[n] = current_pos
                found = True
                break
            current_pos = max(current_pos, end)
        if not found:
            if current_pos < M:
                y[n] = current_pos
                found = True
            else:
                return y[:n], n
    return y, N

